head.b:skin:
:root{--paper:#f7f5f0;--card:#fffefb;--ink:#1b2430;--soft:#475260;--faint:#66707c;--rule:#dcd7cb;--rule2:#b7b0a0;--mark:#ebe6d8;
--accent:#0f6b66;--accent-ink:#ffffff;--accent-bg:#e1efec;--play:#a8441c;--play-ink:#ffffff;--play-bg:#f6e6dc;--play-on-deep:#f0906a;--deep:#10302e;--deep-ink:#f3efe6;--deep-soft:#b9cdca;--deep-rule:#2f504d;--ok:#1f7a4d;--ok-bg:#e0f0e6;--bad:#a3262a;--bad-bg:#f6e0e0;--warn:#8a5a00;
--r:10px;--ui:'Noto Sans Arabic','Segoe UI',Tahoma,sans-serif}
html[data-theme=dark]{--paper:#14181c;--card:#1b2025;--ink:#ece8de;--soft:#b8b4a8;--faint:#989ea6;--rule:#2c333a;--rule2:#47505a;--mark:#232a2e;
--accent:#6cc5bd;--accent-ink:#0d1517;--accent-bg:#1b2e2c;--play:#f0906a;--play-ink:#1a0e08;--play-bg:#33251e;--play-on-deep:#f0906a;--deep:#0c1a19;--deep-ink:#ece8de;--deep-soft:#a9bdba;--deep-rule:#27403d;--ok:#7fd3a2;--ok-bg:#1b2e24;--bad:#f09a9c;--bad-bg:#35201f;--warn:#e0b45a}
*{box-sizing:border-box}html{-webkit-text-size-adjust:100%;scroll-behavior:smooth;scroll-padding-top:72px}
body{margin:0;background:var(--paper);color:var(--ink);font:400 17px/1.8 var(--ui)}
a{color:var(--accent);text-underline-offset:3px}
h1,h2,h3,h4{margin:0;font-weight:700;line-height:1.45}
.wrap{width:min(1120px,100% - 32px);margin-inline:auto}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.skip{position:absolute;top:-80px;inset-inline-start:8px;background:var(--ink);color:var(--paper);padding:10px 14px;z-index:60}.skip:focus{top:8px}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.ic{width:22px;height:22px}
#nav-t{display:none}
/* الأزرار */
.btn,.btn-quiet,.icon-btn{font:600 16px var(--ui);cursor:pointer;transition:background .15s,border-color .15s,transform .1s,color .15s}
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:0 22px;border-radius:var(--r);background:var(--accent);color:var(--accent-ink);text-decoration:none;border:1px solid var(--accent)}
.btn:hover{filter:brightness(.92)}.btn:active{transform:translateY(1px)}
.btn.play{background:var(--play);border-color:var(--play);color:var(--play-ink)}
.btn.alt{background:none;color:var(--ink);border-color:var(--rule2)}
.btn-quiet{min-height:44px;padding:0 16px;background:none;color:var(--ink);border:1px solid var(--rule2);border-radius:var(--r);font-size:14px}.btn-quiet:hover,.icon-btn:hover{border-color:var(--ink)}
.icon-btn{width:44px;height:44px;display:inline-flex;align-items:center;justify-content:center;background:none;color:var(--ink);border:1px solid transparent;border-radius:var(--r);padding:0;list-style:none;text-decoration:none}
.icon-btn::-webkit-details-marker{display:none}
/* الرأس */
.top{background:var(--paper);border-bottom:1px solid var(--rule);position:sticky;top:0;z-index:30}
.bar{display:flex;align-items:center;gap:8px;min-height:64px;position:relative}
.brand{display:inline-flex;align-items:center;gap:10px;font-size:20px;font-weight:700;color:var(--ink);text-decoration:none;margin-inline-end:auto}
.nav{display:none}
.bar-end{display:flex;gap:2px}
.sdrop{position:static}
.sdrop .find{position:absolute;inset-inline:0;top:100%;background:var(--paper);padding:12px 0;border-bottom:1px solid var(--rule);z-index:5}
.sdrop .find input,.sdrop .find button{margin:0}
.menu-btn{order:-1}
.scrim{position:fixed;inset:0;background:rgba(10,14,18,.5);opacity:0;visibility:hidden;transition:opacity .2s,visibility .2s;z-index:40}
.drawer{position:fixed;top:0;bottom:0;inset-inline-start:0;width:min(320px,86vw);background:var(--paper);border-inline-end:1px solid var(--rule);z-index:50;padding:12px 16px 20px;display:flex;flex-direction:column;gap:8px;visibility:hidden;transition:transform .22s,visibility .22s;transform:translateX(100%)}
html[dir=rtl] .drawer{transform:translateX(100%)}html[dir=ltr] .drawer{transform:translateX(-100%)}
.dr-top{display:flex;align-items:center;justify-content:space-between;min-height:48px}
.drawer nav{display:flex;flex-direction:column;margin:8px 0 auto}
.drawer nav a{display:flex;align-items:center;min-height:52px;font-weight:600;color:var(--ink);text-decoration:none;border-bottom:1px solid var(--rule)}
.drawer nav a:hover{color:var(--accent)}
#nav-t:checked~.scrim{opacity:1;visibility:visible}
#nav-t:checked~.drawer{transform:none;visibility:visible}
/* الأقسام */
.sec{padding:44px 0 4px;scroll-margin-top:72px}
.sec-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px}.sec-h h2{font-size:24px}
.tag{font:600 12px var(--ui);color:var(--warn);border:1px solid currentColor;border-radius:6px;padding:1px 9px}
.note{color:var(--soft);font-size:15px;margin:-4px 0 14px}
.eyebrow{font:600 14px var(--ui);color:var(--play);margin:0 0 6px}
.lvl{display:inline-flex;align-items:center;gap:6px;font:600 13px var(--ui);padding:2px 10px;border-radius:999px;background:var(--mark);color:var(--soft)}
.lvl::before{content:'';width:8px;height:8px;border-radius:50%;background:var(--ok)}.lvl-2::before{background:var(--warn)}.lvl-3::before{background:var(--bad)}
/* الهيرو */
.hero{padding:32px 0 28px;border-bottom:1px solid var(--rule)}
.hero-in{display:grid;gap:28px;align-items:center}
.hero h1{font-size:clamp(30px,8vw,52px);line-height:1.3}
.hero .lede{font-size:18px;color:var(--soft);max-width:52ch;margin:12px 0 22px}
.cta-row{display:flex;gap:10px;flex-wrap:wrap}.cta-row .btn{flex:1 1 150px}
/* الألعاب */
.soon{margin-top:10px;font:600 14px var(--ui);color:var(--faint)}
/* التحدي اليومي */
/* المعرفة */
.topics{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.topics a{display:block;height:100%;padding:14px;background:var(--card);border:1px solid var(--rule);border-radius:var(--r);text-decoration:none;color:var(--ink);transition:border-color .15s,background .15s}
.topics a:hover{border-color:var(--accent);background:var(--accent-bg)}
.topics b{display:block;font-size:16px;line-height:1.5}.topics span{display:block;color:var(--soft);font-size:14px;line-height:1.6;margin-top:4px}
/* المقالات */
.posts{list-style:none;margin:0;padding:0;border-top:2px solid var(--ink)}
.posts:empty{border:0}.posts:empty::after{content:attr(data-empty);display:block;padding:28px;text-align:center;color:var(--soft);background:var(--card);border:1px dashed var(--rule2);border-radius:var(--r)}
.posts li{padding:16px 0;border-bottom:1px solid var(--rule)}
.posts p{margin:4px 0 0;color:var(--soft);font-size:15px;line-height:1.7}
.meta{display:flex;flex-wrap:wrap;gap:2px 12px;font-size:13px;color:var(--faint)}.meta span:first-child{color:var(--accent);font-weight:600}
.more{margin:14px 0 0}
/* التقدم */
.prog{display:grid;gap:14px}
.lvlcard{background:var(--card);border:1px solid var(--rule);border-radius:14px;padding:18px}
.lv-top{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:10px}.lv-top span{color:var(--soft);font-size:15px}.lvlcard p{margin:8px 0 0;color:var(--soft);font-size:15px}
.g-prog{height:10px;border-radius:5px;background:var(--mark);overflow:hidden}.g-prog i{display:block;height:100%;background:var(--accent);border-radius:5px;transition:width .4s}.g-prog.big{height:14px;border-radius:7px}
.badges{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.badge{display:flex;align-items:center;gap:10px;background:var(--card);border:1px solid var(--rule);border-radius:var(--r);padding:12px;font-size:14px;font-weight:600;line-height:1.4}
.bd{width:44px;height:44px;flex:none}.b-f{fill:var(--play)}.b-l{fill:none;stroke:var(--faint);stroke-width:3}.b-s{fill:none;stroke:var(--faint);stroke-width:3;stroke-linecap:round}
.badge.locked{opacity:.55}.badge:not(.earned):not(.locked) .b-f{fill:var(--mark);stroke:var(--faint);stroke-width:2}
.badge.earned{border-color:var(--play);animation:pop .5s ease-out}
@keyframes pop{0%{transform:scale(.94)}60%{transform:scale(1.03)}100%{transform:none}}
.method{display:grid;border-top:2px solid var(--ink)}.method div{padding:16px 0;border-bottom:1px solid var(--rule)}.method h3{font-size:17px}.method p{margin:2px 0 0;color:var(--soft);font-size:15px}
/* صفحات المحتوى */
.page{padding:24px 0}
.crumbs{font-size:13px;color:var(--faint);margin-bottom:10px}.crumbs a{color:var(--faint)}
.page h1{font-size:clamp(26px,6vw,38px);margin-bottom:10px}
.labels{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px}.labels a{font-size:13px;padding:2px 10px;border:1px solid var(--rule2);border-radius:6px;color:var(--soft);text-decoration:none}
.byline{display:flex;gap:14px;flex-wrap:wrap;font-size:14px;color:var(--faint);margin-bottom:18px}
.prose>p,.prose>ul,.prose>ol,.prose>h2,.prose>h3,.prose>blockquote,.prose>table{max-width:68ch}
.prose h2{font-size:23px;margin:1.8em 0 .4em}.prose h3{font-size:19px;margin:1.4em 0 .3em}.prose p,.prose li{margin:.8em 0}.prose img{max-width:100%;height:auto}
.prose table{border-collapse:collapse;width:100%;display:block;overflow-x:auto}.prose th,.prose td{border:1px solid var(--rule2);padding:8px 12px;text-align:start}
.pager{display:flex;justify-content:space-between;gap:12px;margin-top:30px;font-weight:600}
.lede{color:var(--soft)}
.find{display:flex;max-width:640px;margin-bottom:18px}
.find input{flex:1;min-width:0;min-height:52px;font:400 17px var(--ui);padding:0 16px;border:1px solid var(--ink);border-inline-end:0;background:var(--card);color:var(--ink);border-start-start-radius:var(--r);border-end-start-radius:var(--r)}
.find button{position:relative;min-height:52px;padding:0 22px;font:600 16px var(--ui);border:1px solid var(--accent);background:var(--accent);color:var(--accent-ink);cursor:pointer;border-start-end-radius:var(--r);border-end-end-radius:var(--r)}
.find button.busy{color:transparent}.find button.busy::after{content:'';position:absolute;inset:0;margin:auto;width:20px;height:20px;border:3px solid var(--accent-ink);border-top-color:transparent;border-radius:50%;animation:spin .7s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.sdrop .find{margin:0 auto;width:min(1120px,100% - 32px)}
.err{padding:56px 0;text-align:center}.err .find{margin:20px auto}.err h1{font-size:30px}
/* لوحات نماذج الألعاب */
.board .lede{max-width:62ch}
.screens{display:grid;gap:22px;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));margin:20px 0}
.screen{margin:0}.screen figcaption{font-size:14px;font-weight:600;color:var(--faint);margin-top:8px;text-align:center}
.phone{max-width:340px;margin-inline:auto;border:1px solid var(--rule2);border-radius:26px;padding:18px 16px;background:var(--paper);min-height:480px;display:flex;flex-direction:column;gap:12px;box-shadow:0 1px 0 var(--rule)}
.g-head{display:grid;gap:8px}.g-row{display:flex;justify-content:space-between;font-size:14px;color:var(--soft);font-weight:600}
.timer{font-variant-numeric:tabular-nums;color:var(--play)}
.q{font-size:19px;line-height:1.6}
.opts,.rows,.tf{display:grid;gap:8px}.tf{grid-template-columns:1fr 1fr}
.opt{display:flex;align-items:center;gap:10px;min-height:48px;padding:6px 12px;border:1px solid var(--rule2);border-radius:var(--r);background:var(--card);font-size:16px;transition:background .15s,border-color .15s}
.opt .ol{width:26px;height:26px;border-radius:50%;background:var(--mark);display:grid;place-items:center;font-size:13px;font-weight:700;flex:none}
.opt .mk{margin-inline-start:auto;font-size:16px}
.opt.big{min-height:84px;justify-content:center;font-size:20px;font-weight:700}
.opt.ok{background:var(--ok-bg);border-color:var(--ok);color:var(--ok)}.opt.bad{background:var(--bad-bg);border-color:var(--bad);color:var(--bad)}
.msg{border-radius:var(--r);padding:10px 14px;font-size:14px;line-height:1.7}.msg p{margin:2px 0 0;color:var(--ink)}
.msg.ok{background:var(--ok-bg);border:1px solid var(--ok)}.msg.ok b{color:var(--ok)}.msg.err{background:var(--bad-bg);border:1px solid var(--bad)}.msg.err b{color:var(--bad)}
.cta{margin-top:auto;display:flex;gap:8px;flex-wrap:wrap}.cta .btn{flex:1}
.row{display:flex;align-items:center;gap:10px;min-height:52px;padding:6px 12px;border:1px solid var(--rule2);border-radius:var(--r);background:var(--card);font-size:15px;line-height:1.5}
.row .grip{color:var(--faint);letter-spacing:0}.row .num{margin-inline-start:auto;width:26px;height:26px;border-radius:50%;background:var(--mark);display:grid;place-items:center;font-size:13px;font-weight:700}
.row.ok{border-color:var(--ok);background:var(--ok-bg)}.row.bad{border-color:var(--bad);background:var(--bad-bg)}
.mgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.mc{aspect-ratio:1;border-radius:12px;background:var(--accent);display:grid;place-items:center;font-size:26px;font-weight:700;color:var(--accent-ink)}
.mc.up{background:var(--card);border:2px solid var(--play);color:var(--ink)}.mc.done{background:var(--ok-bg);border:2px solid var(--ok);color:var(--ok)}
.hint{margin:0;color:var(--soft);font-size:15px}
.tiles{display:flex;gap:8px;justify-content:center;direction:rtl}.tile{width:52px;height:60px;border-radius:12px;border:2px solid var(--rule2);display:grid;place-items:center;font-size:26px;font-weight:700;background:var(--card)}.tile.on{border-color:var(--ok);background:var(--ok-bg);color:var(--ok)}
.keys{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;direction:rtl}.key{min-height:40px;border-radius:8px;border:1px solid var(--rule2);display:grid;place-items:center;font-weight:600;background:var(--card)}.key.ok{background:var(--ok-bg);border-color:var(--ok);color:var(--ok)}.key.bad{opacity:.4;text-decoration:line-through}
.end{display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center;flex:1}
.end h3{font-size:24px}.end p{margin:0;color:var(--soft)}.end .sub{font-size:14px}
.ring{--p:80;width:120px;height:120px;border-radius:50%;background:conic-gradient(var(--accent) calc(var(--p)*1%),var(--mark) 0);display:grid;place-items:center;margin-top:8px}
.ring b{width:92px;height:92px;border-radius:50%;background:var(--paper);display:grid;place-items:center;font-size:24px}
.lvlbar{width:100%;display:grid;gap:6px;font-size:14px;font-weight:600;color:var(--soft);text-align:start}
/* التذييل */
.foot{margin-top:56px;border-top:2px solid var(--ink);padding-top:28px;font-size:15px}
.foot-grid{display:grid;gap:24px}.foot-brand{font-size:20px;font-weight:700}.foot p{margin:6px 0 0;color:var(--soft);max-width:36ch}
.foot h4{font-size:14px;color:var(--faint);margin-bottom:6px}.foot ul{list-style:none;margin:0;padding:0;columns:2;column-gap:16px}
.foot li a{display:inline-block;padding:6px 0;color:var(--ink);text-decoration:none}.foot li a:hover{color:var(--accent);text-decoration:underline}
.foot-end{border-top:1px solid var(--rule);margin-top:24px;padding:16px 0 24px;color:var(--faint);font-size:14px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
@media print{.top,.foot,.drawer,.find{display:none}}

/* ====== هوية تحريرية جديدة ====== */
.glyph{width:34px;height:34px;flex:none}
.glyph .g-l{fill:none;stroke:currentColor;stroke-width:2.5;opacity:.6}.glyph .g-f{fill:var(--play)}.glyph .g-w{fill:none;stroke:#fff;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}.glyph .g-s{fill:none;stroke:currentColor;stroke-width:3;stroke-linecap:round;opacity:.6}
.thumb-g{width:100%;height:100%}
.hero{padding:28px 0 36px;border-bottom:2px solid var(--ink)}
.hero-in{display:grid;gap:26px;align-items:start}
.hero h1{font-size:clamp(36px,10vw,68px);line-height:1.2;letter-spacing:0;font-weight:700}
.hl{background:linear-gradient(transparent 62%,var(--play-bg) 62%);color:inherit;padding:0 2px;box-decoration-break:clone}
html[data-theme=dark] .hl{background:linear-gradient(transparent 62%,var(--play-bg) 62%)}
.hero .lede{font-size:19px;max-width:30ch;margin:14px 0 20px}
.cta-row{display:flex;gap:10px;flex-wrap:wrap}.cta-row .btn{flex:1 1 140px}
/* السؤال الحي */
.live{border:2px solid var(--ink);border-radius:16px;background:var(--card);padding:18px;display:grid;gap:14px}
.live-h{display:flex;justify-content:space-between;font:600 13px var(--ui);color:var(--play)}.live-h span:last-child{color:var(--faint);font-variant-numeric:tabular-nums}
.live-q{font-size:22px;line-height:1.55}
.live-o{display:grid;gap:8px}
.lo{display:flex;align-items:center;gap:12px;min-height:52px;padding:6px 14px;border:1px solid var(--rule2);border-radius:12px;background:var(--paper);color:var(--ink);font:500 17px var(--ui);cursor:pointer;text-align:start;transition:border-color .15s,background .15s,transform .1s}
.lo:hover:not([disabled]){border-color:var(--accent);background:var(--accent-bg)}.lo:active:not([disabled]){transform:scale(.99)}
.lo .ol{width:28px;height:28px;border-radius:50%;background:var(--mark);display:grid;place-items:center;font-size:14px;font-weight:700;flex:none}
.lo[disabled]{cursor:default}.lo.ok{background:var(--ok-bg);border-color:var(--ok);color:var(--ok)}.lo.bad{background:var(--bad-bg);border-color:var(--bad);color:var(--bad)}.lo.dim{opacity:.55}
.live-fb{border-radius:12px;padding:12px 14px;font-size:15px;line-height:1.75}.live-fb b{display:block}.live-fb.ok{background:var(--ok-bg);border:1px solid var(--ok)}.live-fb.ok b{color:var(--ok)}.live-fb.bad{background:var(--bad-bg);border:1px solid var(--bad)}.live-fb.bad b{color:var(--bad)}.live-fb p{margin:2px 0 0}
.live-f{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;min-height:20px}#lv-score{font:600 14px var(--ui);color:var(--soft)}
.live-end{text-align:center;display:grid;gap:10px;justify-items:center;padding:8px 0}.live-end h2{font-size:24px}.live-end p{margin:0;color:var(--soft)}
/* مسرح الألعاب */
.stage{background:var(--deep);color:var(--deep-ink);margin-top:44px;padding:40px 0 44px}
.stage .sec-h h2{color:var(--deep-ink)}.stage .tag{color:#f0b98f;border-color:#f0b98f}
html[data-theme=dark] .stage .tag{color:var(--warn);border-color:var(--warn)}
.stage-note{margin:-4px 0 20px;color:var(--deep-soft);font-size:15px}
.stage-grid{display:grid;gap:20px}
.tabs{display:grid;gap:0;border-top:1px solid var(--deep-rule)}
.tab{display:grid;grid-template-columns:34px 1fr auto;align-items:center;gap:10px;min-height:56px;padding:8px 12px;border-bottom:1px solid var(--deep-rule);cursor:pointer;color:var(--deep-ink);border-radius:0;transition:background .15s,color .15s}
.tab:hover{background:var(--deep-rule)}
.tn{font:700 14px var(--ui);color:var(--deep-soft);font-variant-numeric:tabular-nums}.tt{font:600 17px var(--ui)}
.tab .lvl{background:transparent;border:1px solid var(--deep-rule);color:inherit;font-size:12px}
.panes .pane{display:none;gap:22px;align-items:center}
.pane h3{font-size:clamp(26px,6vw,38px);line-height:1.3}.pane p{color:var(--deep-soft);font-size:18px;margin:8px 0 14px}
.pane-meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:16px}.pane .lvl{background:var(--deep-rule);color:var(--deep-ink)}
.pane .soon{color:var(--deep-soft)}
.pane .screen figcaption{color:var(--deep-soft)}
.pane .phone{min-height:0;max-height:430px;overflow:hidden}
/* فهرس المواضيع */
.fahras{list-style:none;margin:0;padding:0;border-top:2px solid var(--ink)}
.fahras a{display:grid;grid-template-columns:44px 1fr 24px;gap:10px;align-items:center;padding:16px 4px;border-bottom:1px solid var(--rule);color:var(--ink);text-decoration:none;transition:padding .18s,background .15s}
.fahras a:hover{background:var(--accent-bg);padding-inline-start:14px}
.fn{font:700 15px var(--ui);color:var(--play);font-variant-numeric:tabular-nums}.ft{display:block;font:700 24px/1.4 var(--ui)}.fd{display:block;color:var(--soft);font-size:15px;line-height:1.6}.fg{color:var(--faint);transition:transform .18s}
.fahras a:hover .fg{transform:translateX(-6px)}html[dir=ltr] .fahras a:hover .fg{transform:translateX(6px)}
/* مقال مميز وقائمة */
.feat{display:grid;gap:14px;padding-bottom:22px;border-bottom:2px solid var(--ink)}
.feat-img{display:block;border-radius:14px;background:var(--accent-bg);overflow:hidden;aspect-ratio:16/10;color:var(--accent)}.feat-img img{width:100%;height:100%;object-fit:cover}.feat-img .glyph{width:100%;height:100%;padding:28%}
.feat h3{font-size:clamp(26px,6vw,36px);line-height:1.4;margin:6px 0}.feat h3 a{color:var(--ink);text-decoration:none}.feat h3 a:hover{color:var(--accent)}.feat p{color:var(--soft);margin:0 0 10px}
.tag-feat{color:var(--play)!important;font-weight:700}
.read{font-weight:700}
.feat-wrap:empty::after{content:attr(data-empty);display:block;padding:28px;text-align:center;color:var(--soft);background:var(--card);border:1px dashed var(--rule2);border-radius:var(--r)}
.rows-list{list-style:none;margin:0;padding:0}
.rl{display:grid;grid-template-columns:34px 1fr;gap:10px;padding:16px 0;border-bottom:1px solid var(--rule);color:var(--ink);text-decoration:none}
.rl:hover .rl-t{color:var(--accent)}
.rl-n{font:700 28px/1.2 var(--ui);color:var(--rule2);font-variant-numeric:tabular-nums}.rl-b{display:grid;gap:2px}.rl-t{font:700 19px/1.55 var(--ui)}.rl-s{color:var(--soft);font-size:15px;line-height:1.7}
/* المنهج */
.method{list-style:none;margin:0;padding:0;border-top:2px solid var(--ink);display:grid}
.method li{display:grid;grid-template-columns:44px 1fr;column-gap:10px;padding:16px 0;border-bottom:1px solid var(--rule)}
.mn{grid-row:span 2;font:700 34px/1 var(--ui);color:var(--play)}.method h3{font-size:18px}.method p{margin:2px 0 0;color:var(--soft);font-size:15px}
.method div{border:0}
@media(min-width:900px){
 .menu-btn,.drawer,.scrim{display:none}.nav{display:flex;gap:2px;margin-inline-end:auto}
 .nav a{display:flex;align-items:center;min-height:44px;padding:0 12px;color:var(--ink);text-decoration:none;font-weight:600;font-size:15px;border-bottom:2px solid transparent}.nav a:hover{border-bottom-color:var(--play)}
 .brand{margin-inline-end:24px}
 .hero{padding:64px 0 64px}.hero-in{grid-template-columns:1.15fr .85fr;gap:56px;align-items:center}
 .live{padding:26px}.live-q{font-size:25px}
 .stage{padding:64px 0 72px}.stage-grid{grid-template-columns:340px 1fr;gap:56px;align-items:start}
 .panes .pane{grid-template-columns:1fr 340px}
 .pane .phone{max-height:none}
 .fahras{display:grid;grid-template-columns:1fr 1fr;column-gap:56px}
 .feat{grid-template-columns:1.2fr 1fr;gap:36px;align-items:center}.feat-img{aspect-ratio:4/3}
 .rows-list{display:grid;grid-template-columns:1fr 1fr;column-gap:56px}
 .prog{grid-template-columns:1fr 1.4fr;align-items:start}.badges{grid-template-columns:repeat(4,1fr)}
 .method{grid-template-columns:repeat(3,1fr);gap:0 36px}.method li{border-bottom:0;padding:20px 0}
 .foot-grid{grid-template-columns:1.4fr 1.4fr 1fr}.foot ul{columns:1}.foot-grid>div:nth-child(2) ul{columns:2}
}
@media(min-width:620px) and (max-width:899px){.badges{grid-template-columns:repeat(4,1fr)}}
.stage .btn.play{background:var(--play-on-deep);border-color:var(--play-on-deep);color:#1a0e08}
.stage .tab .tn{color:var(--deep-soft)}
[hidden]{display:none!important}
.pane .phone{color:var(--ink)}.pane .phone .q,.pane .phone h3{color:var(--ink)}.pane .phone .end p{color:var(--soft)}
.feat-img{display:grid;place-items:center}.feat-img .glyph{width:88px;height:88px;padding:0;background:none}
.pane .phone .q{font-size:19px;line-height:1.6}.pane .phone .end h3{font-size:24px}
/* BASIRA identity layer — appended after the base theme. */
:root{--brand-ink:#152d43;--brand-accent:#0f766e;--brand-spark:#e6a23c;}
html[data-theme=dark]{--brand-ink:#e9f1f4;--brand-accent:#72c9bd;--brand-spark:#f2bd68;}
.brand-lockup{display:inline-flex;align-items:center;gap:9px;direction:ltr;white-space:nowrap;}
.brand-symbol{width:34px;height:34px;display:block;flex:none;overflow:visible;}
.brand-symbol .bs-line{fill:none;stroke:var(--brand-accent);stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;}
.brand-symbol .bs-core{fill:var(--brand-spark);stroke:var(--brand-ink);stroke-width:1.2;stroke-linejoin:round;}
.brand-symbol .bs-ray{fill:none;stroke:var(--brand-ink);stroke-width:2;stroke-linecap:round;}
.brand-names{display:flex;flex-direction:column;line-height:1.05;gap:3px;text-align:start;}
.brand-names b{font:800 17px/1.05 'Segoe UI',Arial,sans-serif;letter-spacing:1.4px;color:var(--brand-ink);}
.brand-names small{font:700 12px/1.2 'Noto Sans Arabic','Segoe UI',Tahoma,sans-serif;color:var(--brand-accent);}
.foot-brand .brand-symbol{width:38px;height:38px;}
.foot-brand .brand-names b{font-size:19px;}
.hero .eyebrow{display:flex;flex-wrap:wrap;gap:8px;align-items:center;}
.eyebrow-ar{font-family:'Noto Sans Arabic','Segoe UI',Tahoma,sans-serif;}
/* واجهة الألعاب الحقيقية */
.bsr-game{min-height:120px}
.bg{display:block}
.bsr-game{background:var(--card);color:var(--ink);border:1px solid var(--rule);border-radius:16px;padding:18px;max-width:640px}
.bsr-game button{font-family:var(--ui)}
.bg-rules{margin:0 0 14px;font-size:16px;color:var(--soft);line-height:1.8}
.bg-lvs{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:10px}
.bg-lv{min-height:48px;border:1px solid var(--rule2);background:var(--paper);color:var(--ink);border-radius:var(--r);font-size:16px;font-weight:600;cursor:pointer}
.bg-lv[aria-checked=true]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}
.bg-lvd,.bg-best{margin:0 0 6px;font-size:15px;color:var(--soft)}
.bg-go{margin-top:12px;width:100%}
.bg-head{margin-bottom:14px}
.bg-bar{height:6px;background:var(--mark);border-radius:3px;overflow:hidden}
.bg-bar i{display:block;height:100%;background:var(--accent)}
.bg-row{display:flex;justify-content:space-between;gap:10px;margin-top:8px;font-size:14px;color:var(--soft);font-weight:600}
.bg-q{font-size:20px;line-height:1.7;margin:0 0 14px}
.bg-q2{margin:0 0 10px;font-size:14px;color:var(--soft)}
.bg-opts{display:grid;gap:10px}
.bg-opt{display:flex;align-items:center;gap:12px;min-height:52px;width:100%;padding:10px 14px;text-align:start;background:var(--paper);color:var(--ink);border:1px solid var(--rule2);border-radius:var(--r);font-size:17px;cursor:pointer}
.bg-opt:hover:not(:disabled){border-color:var(--ink)}
.bg-opt:disabled{cursor:default}
.bg-ol{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--mark);font-weight:700;font-size:14px;flex:none}
.bg-opt.ok{border:2px solid var(--ok);background:var(--accent-bg)}
.bg-opt.bad{border:2px solid var(--play);background:var(--play-bg)}
.bg-opt.dim{opacity:.6}
.bg-mk{margin-inline-start:auto;font-size:18px}
.bg-tf{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.bg-big{justify-content:center;font-size:20px;font-weight:700;min-height:64px}
.bg-fb{margin-top:14px;padding:12px 14px;border-radius:var(--r);border:1px solid var(--rule2)}
.bg-fb.ok{border-color:var(--ok);background:var(--accent-bg)}
.bg-fb.bad{border-color:var(--play);background:var(--play-bg)}
.bg-fb p{margin:4px 0 12px;font-size:16px;line-height:1.7}
.bg-fb[hidden],.bsr-game [hidden]{display:none!important}
.bg-rows{list-style:none;margin:0 0 12px;padding:0;display:grid;gap:8px}
.bg-row2{display:flex;align-items:center;gap:8px;min-height:52px;padding:6px 12px;background:var(--paper);border:1px solid var(--rule2);border-radius:var(--r)}
.bg-row2.ok{border:2px solid var(--ok)}.bg-row2.bad{border:2px solid var(--play)}
.bg-rt{flex:1;font-size:16px;line-height:1.6}
.bg-mv{width:44px;height:44px;border:1px solid var(--rule2);background:var(--card);color:var(--ink);border-radius:var(--r);cursor:pointer;font-size:14px}
.bg-mv:disabled{opacity:.35;cursor:default}
.bg-hint{margin:0 0 12px;font-size:17px;min-height:1.6em}
.bg-tiles{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin:6px 0 12px;direction:rtl}
.bg-tile{display:grid;place-items:center;width:46px;height:56px;border:2px solid var(--rule2);border-radius:10px;font-size:26px;font-weight:700;background:var(--paper)}
.bg-tile.on{border-color:var(--accent);background:var(--accent-bg)}
.bg-left{margin:0 0 10px;text-align:center;font-size:14px;color:var(--soft)}
.bg-keys{display:grid;grid-template-columns:repeat(8,1fr);gap:6px;direction:rtl}
.bg-key{min-height:44px;border:1px solid var(--rule2);background:var(--paper);color:var(--ink);border-radius:8px;font-size:18px;font-weight:600;cursor:pointer;padding:0}
.bg-key.ok{background:var(--accent-bg);border-color:var(--ok)}.bg-key.bad{background:var(--play-bg);border-color:var(--play);text-decoration:line-through}
.bg-key:disabled{cursor:default}
.bg-hintbtn{margin-bottom:12px;min-height:44px}
.bg-grid{display:grid;gap:8px}.bg-grid.g2{grid-template-columns:repeat(2,1fr)}.bg-grid.g3{grid-template-columns:repeat(3,1fr)}
.bg-card{min-height:72px;padding:6px;border:2px solid var(--rule2);border-radius:12px;background:var(--deep);color:var(--deep-ink);font-size:15px;font-weight:600;cursor:pointer;line-height:1.4}
.bg-card.up{background:var(--paper);color:var(--ink);border-color:var(--accent)}
.bg-card.done{background:var(--accent-bg);color:var(--ink);border-color:var(--ok);opacity:1}
.bg-card:disabled{cursor:default}
.bg-end{text-align:center}
.bg-big2{font-size:40px;font-weight:700;line-height:1.3}
.bg-end.win .bg-big2{color:var(--ok)}.bg-end.lose .bg-big2{color:var(--play)}
.bg-end h3{margin:4px 0 8px;font-size:22px}.bg-end p{margin:4px 0}
.bg-meta{font-size:14px;color:var(--soft)}.bg-record{font-weight:700;color:var(--ok)}
.bg-rev{text-align:start;margin:14px 0;font-size:15px}.bg-rev summary{cursor:pointer;min-height:44px;display:flex;align-items:center;font-weight:600}
.bg-rev ul{margin:0;padding-inline-start:20px}.bg-rev li{margin-bottom:8px}
.bg-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}
.bg-stats{width:100%;border-collapse:collapse;font-size:15px;margin-bottom:12px}
.bg-stats caption{text-align:start;font-weight:700;margin-bottom:6px}
.bg-stats th,.bg-stats td{padding:8px 6px;border-bottom:1px solid var(--rule);text-align:start}
.stage .bsr-game{max-width:none}
.game-page .bsr-game{margin:0 auto 24px}
.game-page .game-about{max-width:640px;margin:0 auto}
@media(max-width:380px){.bg-key{font-size:16px}.bg-tile{width:40px;height:50px}}
#gm-mcq:checked~.tabs [for=gm-mcq]{background:var(--paper);color:var(--ink);border-color:var(--paper)}#gm-mcq:checked~.tabs [for=gm-mcq] .tn{color:var(--play)}#gm-mcq:checked~.panes .p-mcq{display:grid}#gm-mcq:focus-visible~.tabs [for=gm-mcq]{outline:3px solid var(--play-on-deep);outline-offset:2px}
#gm-truefalse:checked~.tabs [for=gm-truefalse]{background:var(--paper);color:var(--ink);border-color:var(--paper)}#gm-truefalse:checked~.tabs [for=gm-truefalse] .tn{color:var(--play)}#gm-truefalse:checked~.panes .p-truefalse{display:grid}#gm-truefalse:focus-visible~.tabs [for=gm-truefalse]{outline:3px solid var(--play-on-deep);outline-offset:2px}
#gm-order:checked~.tabs [for=gm-order]{background:var(--paper);color:var(--ink);border-color:var(--paper)}#gm-order:checked~.tabs [for=gm-order] .tn{color:var(--play)}#gm-order:checked~.panes .p-order{display:grid}#gm-order:focus-visible~.tabs [for=gm-order]{outline:3px solid var(--play-on-deep);outline-offset:2px}
#gm-memory:checked~.tabs [for=gm-memory]{background:var(--paper);color:var(--ink);border-color:var(--paper)}#gm-memory:checked~.tabs [for=gm-memory] .tn{color:var(--play)}#gm-memory:checked~.panes .p-memory{display:grid}#gm-memory:focus-visible~.tabs [for=gm-memory]{outline:3px solid var(--play-on-deep);outline-offset:2px}
#gm-word:checked~.tabs [for=gm-word]{background:var(--paper);color:var(--ink);border-color:var(--paper)}#gm-word:checked~.tabs [for=gm-word] .tn{color:var(--play)}#gm-word:checked~.panes .p-word{display:grid}#gm-word:focus-visible~.tabs [for=gm-word]{outline:3px solid var(--play-on-deep);outline-offset:2px}

body.script:
//
(function(){
  var d=document.documentElement,bs=document.querySelectorAll('.js-theme'),nav=document.getElementById('nav-t');
  function label(){var t=d.getAttribute('data-theme')==='dark'?'الوضع الفاتح':'الوضع الداكن';for(var i=0;i<bs.length;i++)bs[i].textContent=t;}
  label();
  for(var i=0;i<bs.length;i++)bs[i].addEventListener('click',function(){
    var dark=d.getAttribute('data-theme')!=='dark';
    if(dark)d.setAttribute('data-theme','dark');else d.removeAttribute('data-theme');
    try{localStorage.setItem('site-theme',dark?'dark':'light');}catch(e){}
    label();
  });
  function closeNav(){if(nav)nav.checked=false;}
  var dl=document.querySelectorAll('.drawer a');for(i=0;i<dl.length;i++)dl[i].addEventListener('click',closeNav);
  var lb=document.querySelectorAll('label[role=button]');
  for(i=0;i<lb.length;i++)lb[i].addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();this.click();}});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeNav();var s=document.querySelector('.sdrop');if(s)s.removeAttribute('open');}});
  var fs=document.querySelectorAll('form.find');
  for(i=0;i<fs.length;i++)fs[i].addEventListener('submit',function(e){
    var q=this.querySelector('input[name=q]');
    if(q&&!q.value.trim()){e.preventDefault();q.focus();return;}
    var b=this.querySelector('button');if(b){b.classList.add('busy');b.setAttribute('aria-busy','true');}
  });

  /* سؤال اليوم: أسئلة مراجَعة مخزنة في القالب. بلا خادم وبلا نقاط، والنتيجة لهذه الجلسة فقط. */
  var Q=[{"q": "ما العدد التالي: 2، 6، 12، 20، ؟", "o": ["28", "30", "32", "24"], "a": 1, "x": "الفروق بين الأعداد المتتالية هي 4 ثم 6 ثم 8 ثم 10، فالعدد التالي 20 + 10 = 30. وكل حدّ هو n × (n+1).", "l": "متوسط"}, {"q": "ما أكبر كواكب المجموعة الشمسية؟", "o": ["زحل", "المشتري", "نبتون", "الأرض"], "a": 1, "x": "المشتري هو الأكبر، وكتلته أكبر من كتلة بقية الكواكب مجتمعة.", "l": "سهل"}, {"q": "أي هذه الأنهار يصب في البحر المتوسط؟", "o": ["الأمازون", "الدانوب", "النيل", "المسيسيبي"], "a": 2, "x": "يصب النيل في البحر المتوسط شمال مصر. أما الأمازون فيصب في المحيط الأطلسي، والدانوب في البحر الأسود، والمسيسيبي في خليج المكسيك.", "l": "سهل"}, {"q": "ما أصغر عدد أولي؟", "o": ["0", "1", "2", "3"], "a": 2, "x": "العدد الأولي له قاسمان بالضبط هما 1 ونفسه. العدد 1 له قاسم واحد فقط فليس أولياً، والعدد 2 هو أصغر عدد يحقق الشرط.", "l": "متوسط"}, {"q": "كم يوماً في السنة الكبيسة؟", "o": ["365", "364", "367", "366"], "a": 3, "x": "السنة الكبيسة في التقويم الميلادي 366 يوماً، لأن شهر فبراير فيها 29 يوماً.", "l": "سهل"}, {"q": "أي كوكب يُعرف بالكوكب الأحمر؟", "o": ["المريخ", "الزهرة", "عطارد", "أورانوس"], "a": 0, "x": "المريخ، ويرجع لونه الأحمر إلى أكاسيد الحديد في تربته.", "l": "سهل"}],live=document.getElementById('live');
  if(live&&Q.length){
    var $=function(id){return document.getElementById(id);},qe=$('lv-q'),oe=$('lv-o'),fb=$('lv-fb'),nx=$('lv-next'),sc=$('lv-score'),nn=$('lv-n');
    var day=Math.floor(new Date().getTime()/86400000),idx=day%Q.length,done=0,right=0,locked=false;
    var AR='أبجد';
    function show(){
      var q=Q[idx];locked=false;qe.textContent=q.q;oe.innerHTML='';fb.hidden=true;fb.className='live-fb';nx.hidden=true;
      nn.textContent=(done+1)+' من '+Q.length;sc.textContent=done?('الصحيحة: '+right+' من '+done):'';
      q.o.forEach(function(t,i){
        var b=document.createElement('button');b.type='button';b.className='lo';
        var l=document.createElement('span');l.className='ol';l.textContent=AR.charAt(i);
        var s2=document.createElement('span');s2.textContent=t;b.appendChild(l);b.appendChild(s2);
        b.addEventListener('click',function(){pick(i,b);});oe.appendChild(b);
      });
    }
    function pick(i,btn){
      if(locked)return;locked=true;var q=Q[idx],ok=i===q.a,bs=oe.children;done++;if(ok)right++;
      for(var k=0;k<bs.length;k++){bs[k].disabled=true;if(k===q.a)bs[k].classList.add('ok');else if(k===i)bs[k].classList.add('bad');else bs[k].classList.add('dim');}
      fb.hidden=false;fb.className='live-fb '+(ok?'ok':'bad');
      fb.innerHTML='';var t=document.createElement('b');t.textContent=ok?'إجابة صحيحة':'إجابة خاطئة';var p=document.createElement('p');p.textContent=q.x;fb.appendChild(t);fb.appendChild(p);
      sc.textContent='الصحيحة: '+right+' من '+done;
      nx.hidden=false;nx.textContent=done>=Q.length?'النتيجة':'سؤال آخر';nx.focus();
    }
    nx.addEventListener('click',function(){
      if(done>=Q.length){
        live.innerHTML='';var w=document.createElement('div');w.className='live-end';
        var h=document.createElement('h2');h.textContent='أكملت الجولة: '+right+' من '+Q.length;
        var p=document.createElement('p');p.textContent='النتيجة لهذه الجلسة فقط ولا تُحفظ.';
        var r=document.createElement('button');r.className='btn';r.type='button';r.textContent='أعد الجولة';
        r.addEventListener('click',function(){location.reload();});
        w.appendChild(h);w.appendChild(p);w.appendChild(r);live.appendChild(w);r.focus();return;
      }
      idx=(idx+1)%Q.length;show();
    });
    show();
  }
})();

/* محرك ألعاب BASIRA: أسئلة مراجَعة مخزنة داخل القالب، بلا خادم ولا ذكاء اصطناعي أثناء اللعب.
